from pathlib import Path
import gzip, hashlib, json
p=Path('experiments/results/inten_origin_invariance/evidence')
rows=[json.loads(l) for l in gzip.open(p/'cases.jsonl.gz','rt')]
metrics=list(rows[0]['metrics'])
def maximum(items,metric):
 finite=[r for r in items if isinstance(r['metrics'][metric],(int,float))]
 worst=max(finite,key=lambda r:r['metrics'][metric])
 return dict(maximum=worst['metrics'][metric],case=worst['id'],finite_count=len(finite),unavailable_count=len(items)-len(finite))
groups=[]
for kind in ('stored_fixture','analytic_control'):
 for stage in ('s2s','s2m','analytic'):
  for shift in (0,100,1000):
   selected=[r for r in rows if r['kind']==kind and r['stage']==stage and r['shift_norm_m']==shift]
   if selected: groups.append(dict(kind=kind,stage=stage,shift_norm_m=shift,cases=len(selected),metrics={m:maximum(selected,m) for m in metrics}))
report=dict(source_sha256=hashlib.sha256((p/'cases.jsonl.gz').read_bytes()).hexdigest(),source_raw_commit='80cfaf23',groups=groups,all_case_controls={m:maximum(rows,m) for m in ('observed_delta_linf','transport_formula_error_m','exact_exp_position_error_m')},raw_solve_nonfinite=sum(not r['raw_solve_finite'] for r in rows),covariant_solve_nonfinite=sum(not r['covariant_solve_finite'] for r in rows),scope='Stage maxima over all declared tuples and shift axes/signs; tuple copies are not independent statistical samples.')
(p.parent/'reported_values.json').write_text(json.dumps(report,indent=2,allow_nan=False)+'\n')
